#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int score[301] = {0};
    int dp[301] = {0};
    for (int index = 1; index <= n; ++index) {
        scanf("%d", &score[index]);
    }

    if (n >= 1) {
        dp[1] = score[1];
    }
    if (n >= 2) {
        dp[2] = score[1] + score[2];
    }
    for (int index = 3; index <= n; ++index) {
        int skip_previous = dp[index - 2];
        int take_previous = dp[index - 3] + score[index - 1];
        dp[index] = (skip_previous > take_previous ? skip_previous : take_previous) + score[index];
    }

    printf("%d\n", dp[n]);
    return 0;
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine().trim());

        int[] score = new int[n + 1];
        int[] dp = new int[n + 1];
        for (int index = 1; index <= n; ++index) {
            score[index] = Integer.parseInt(reader.readLine().trim());
        }

        if (n >= 1) {
            dp[1] = score[1];
        }
        if (n >= 2) {
            dp[2] = score[1] + score[2];
        }
        for (int index = 3; index <= n; ++index) {
            dp[index] = Math.max(dp[index - 2], dp[index - 3] + score[index - 1]) + score[index];
        }

        System.out.println(dp[n]);
    }
}

